#!/usr/bin/env python3"""WAV audio data generator for GD32 I2S demo.Usage:    python gen_wave.pyOutput:    ../Components/drivers/wave_data.c    ../Components/drivers/wave_data.h"""import structimport mathimport osdef gen_wav(duration_s=1.0, sample_rate=8000, freq=440,            channels=1, bits=16, volume=0.4):    """Generate a WAV byte stream (RIFF header + PCM payload)."""    n_frames     = int(duration_s * sample_rate)    bytes_per_smp = bits // 8    data_size    = n_frames * channels * bytes_per_smp    byte_rate    = sample_rate * channels * bytes_per_smp    block_align  = channels * bytes_per_smp    hdr  = b'RIFF' + struct.pack('<I', 36 + data_size) + b'WAVE'    hdr += b'fmt ' + struct.pack('<IHHIIHH',                                 16, 1, channels, sample_rate,                                 byte_rate, block_align, bits)    hdr += b'data' + struct.pack('<I', data_size)    pcm = bytearray()    for i in range(n_frames):        v = int(32767 * volume * math.sin(2 * math.pi * freq * i / sample_rate))        for _ in range(channels):            if bits == 16:                pcm += struct.pack('<h', v)            elif bits == 8:                pcm += struct.pack('<B', (v >> 8) + 128)    return hdr + bytes(pcm)def write_c(path, data):    os.makedirs(os.path.dirname(path), exist_ok=True)    with open(path, 'w', encoding='utf-8', newline='\n') as f:        f.write('/* Auto-generated by tools/gen_wave.py */\n\n')        f.write('#include "wave_data.h"\n\n')        f.write('const uint8_t wavetestdata[] = {\n')        for i, b in enumerate(data):            if i % 16 == 0:                f.write('    ')            f.write('0x%02X, ' % b)            if i % 16 == 15:                f.write('\n')        if len(data) % 16:            f.write('\n')        f.write('};\n\n')        f.write('const uint32_t wavetestdata_len = sizeof(wavetestdata);\n')def write_h(path):    os.makedirs(os.path.dirname(path), exist_ok=True)    with open(path, 'w', encoding='utf-8', newline='\n') as f:        f.write('#ifndef __WAVE_DATA_H\n')        f.write('#define __WAVE_DATA_H\n\n')        f.write('#include <stdint.h>\n\n')        f.write('extern const uint8_t  wavetestdata[];\n')        f.write('extern const uint32_t wavetestdata_len;\n\n')        f.write('#endif /* __WAVE_DATA_H */\n')if __name__ == '__main__':    # Change these parameters to generate different audio    wav = gen_wav(        duration_s=1.0,     # duration in seconds        sample_rate=8000,   # sample rate in Hz        freq=440,           # sine frequency in Hz (440 = A4)        channels=1,         # 1 = mono, 2 = stereo        bits=16,            # bits per sample        volume=0.4,         # 0.0 .. 1.0    )    here = os.path.dirname(os.path.abspath(__file__))    base = os.path.normpath(os.path.join(here, '..', 'Components', 'drivers'))    write_c(os.path.join(base, 'wave_data.c'), wav)    write_h(os.path.join(base, 'wave_data.h'))    print('[OK] wave_data.c : %d bytes (PCM = %d bytes)'          % (len(wav), len(wav) - 44))    print('[OK] wave_data.h : generated')